package com.hanziflow.shared.testgen

import com.hanziflow.shared.CourseJson
import com.hanziflow.shared.fixtureText
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlinx.serialization.encodeToString

/**
 * Golden vectors: TestGenerator.generate() against the real lesson_001 items.json
 * fixture, frozen for seeds 1/2/3. Exact JSON equality on both JVM and JS catches
 * any accidental change to the deterministic output (PRNG, selection order,
 * distractor tiering, serialization) without bumping GENERATOR_VERSION.
 */
class GoldenVectorTest {

    @Test
    fun seed1MatchesFrozenGolden() {
        val items = listOf(CourseJson.items(fixtureText("items.json")))
        val test = TestGenerator.generate(items, "lesson_001", 1, 12)
        assertEquals(GOLDEN_SEED_1, CourseJson.codec.encodeToString(test))
    }

    @Test
    fun seed2MatchesFrozenGolden() {
        val items = listOf(CourseJson.items(fixtureText("items.json")))
        val test = TestGenerator.generate(items, "lesson_001", 2, 12)
        assertEquals(GOLDEN_SEED_2, CourseJson.codec.encodeToString(test))
    }

    @Test
    fun seed3MatchesFrozenGolden() {
        val items = listOf(CourseJson.items(fixtureText("items.json")))
        val test = TestGenerator.generate(items, "lesson_001", 3, 12)
        assertEquals(GOLDEN_SEED_3, CourseJson.codec.encodeToString(test))
    }
}

